	'services/billetterie' => array(
		'en' => array( 'Ticketing', 'Flight tickets at the best fare on every airline, departing from Conakry.', '<p>Our advisers compare the airlines serving Conakry (Air France, Brussels Airlines, Royal Air Maroc, Turkish Airlines, Emirates, ASKY, Air Côte d’Ivoire…) to offer you the best balance of price, schedule and luggage.</p><h2>What we do for you</h2><ul><li>Search for the best fares and the shortest stopovers</li><li>Booking with an option to hold a price</li><li>Seat choice, extra luggage, special meals</li><li>Changes or cancellation according to the ticket conditions</li><li>Group tickets: families, students, delegations</li></ul><h2>How does it work?</h2><ol><li>You send your request (form, WhatsApp or at the agency).</li><li>We offer you 2 or 3 options with prices.</li><li>You confirm and pay (cash, Orange Money, MTN MoMo or card).</li><li>Your e-ticket is sent to you and stays available in your <a href="/mon-espace/">customer area</a>.</li></ol><p>See also our <a href="/destinations/">current deals</a> and our <a href="/blog/">luggage tips</a>.</p>' ),
		'es' => array( 'Billetes de avión', 'Billetes de avión al mejor precio en todas las aerolíneas, desde Conakry.', '<p>Nuestros asesores comparan las aerolíneas que vuelan a Conakry (Air France, Brussels Airlines, Royal Air Maroc, Turkish Airlines, Emirates, ASKY, Air Côte d’Ivoire…) para ofrecerle la mejor relación entre precio, horarios y equipaje.</p><h2>Lo que hacemos por usted</h2><ul><li>Búsqueda de las mejores tarifas y las escalas más cortas</li><li>Reserva con opción para bloquear un precio</li><li>Elección de asiento, equipaje adicional, comidas especiales</li><li>Cambios o cancelación según las condiciones del billete</li><li>Billetes de grupo: familias, estudiantes, delegaciones</li></ul><h2>¿Cómo funciona?</h2><ol><li>Envía su solicitud (formulario, WhatsApp o en la agencia).</li><li>Le proponemos 2 o 3 opciones con precios.</li><li>Usted confirma y paga (efectivo, Orange Money, MTN MoMo o tarjeta).</li><li>Le enviamos su billete electrónico, que queda disponible en su <a href="/mon-espace/">área de cliente</a>.</li></ol><p>Consulte también nuestras <a href="/destinations/">ofertas del momento</a> y nuestros <a href="/blog/">consejos de equipaje</a>.</p>' ),
		'ar' => array( 'حجز التذاكر', 'تذاكر طيران بأفضل الأسعار على جميع شركات الطيران انطلاقًا من كوناكري.', '<p>يقارن مستشارونا شركات الطيران التي تخدم كوناكري (إير فرانس، بروكسل إيرلاينز، الخطوط الملكية المغربية، الخطوط التركية، طيران الإمارات، ASKY، إير كوت ديفوار…) ليقدّموا لك أفضل توازن بين السعر والمواعيد والأمتعة.</p><h2>ما نقوم به من أجلك</h2><ul><li>البحث عن أفضل الأسعار وأقصر التوقفات</li><li>حجز مع خيار تثبيت السعر</li><li>اختيار المقعد، أمتعة إضافية، وجبات خاصة</li><li>التعديل أو الإلغاء حسب شروط التذكرة</li><li>تذاكر جماعية: عائلات، طلاب، وفود</li></ul><h2>كيف يعمل ذلك؟</h2><ol><li>ترسل طلبك (النموذج، واتساب أو في الوكالة).</li><li>نقترح عليك خيارين أو ثلاثة مع الأسعار.</li><li>تؤكد وتدفع (نقدًا، أورانج موني، MTN MoMo أو بالبطاقة).</li><li>تصلك تذكرتك الإلكترونية وتبقى متاحة في <a href="/mon-espace/">مساحة العميل</a>.</li></ol><p>اطّلع أيضًا على <a href="/destinations/">العروض الحالية</a> و<a href="/blog/">نصائح الأمتعة</a>.</p>' ),
